/* Copies the 2J Training Protocol runtime from the frontend (canonical) to the API.
 *
 *   node scripts/sync-protocol.mjs           # write api/lib/protocol/*.js
 *   node scripts/sync-protocol.mjs --check   # fail if the API copy is stale (CI / tests)
 *
 * Same arrangement as scripts/build-coach-library.mjs: the api image never reaches into
 * frontend/, so the server gets a generated, committed copy — byte-identical apart from a
 * "do not edit" header — and validates with exactly the code the builder shows.
 */
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const src = join(root, 'frontend', 'src', 'lib', 'protocol')
const out = join(root, 'api', 'lib', 'protocol')
const HEADER = '// GENERATED by scripts/sync-protocol.mjs from frontend/src/lib/protocol/ — do not edit here.\n'

const files = readdirSync(src).filter(f => f.endsWith('.js') && !f.endsWith('.test.js')).sort()
const check = process.argv.includes('--check')
let stale = []
mkdirSync(out, { recursive: true })
for (const f of files) {
  const want = HEADER + readFileSync(join(src, f), 'utf8').replace(/\r\n/g, '\n')
  let have = null
  try { have = readFileSync(join(out, f), 'utf8').replace(/\r\n/g, '\n') } catch { /* missing = stale */ }
  if (have === want) continue
  if (check) stale.push(f)
  else writeFileSync(join(out, f), want)
}
if (check) {
  if (stale.length) { console.error('api/lib/protocol is out of date (' + stale.join(', ') + ') — run: node scripts/sync-protocol.mjs'); process.exit(1) }
  console.log(`api/lib/protocol in sync (${files.length} files).`)
} else console.log(`Wrote ${files.length} protocol files to api/lib/protocol/.`)
